package com.example.bookmyticket.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="movie_shows")
public class MovieShow { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="movie_id") private Movie movie; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="theatre_id") private Theatre theatre; @Column(nullable=false) private LocalDateTime startTime; @Column(nullable=false,precision=10,scale=2) private BigDecimal ticketPrice; @Column(nullable=false) private Integer totalSeats=48; public MovieShow(){} public MovieShow(Movie m,Theatre t,LocalDateTime s,BigDecimal p,Integer n){movie=m;theatre=t;startTime=s;ticketPrice=p;totalSeats=n;} public Long getId(){return id;} public Movie getMovie(){return movie;} public Theatre getTheatre(){return theatre;} public LocalDateTime getStartTime(){return startTime;} public BigDecimal getTicketPrice(){return ticketPrice;} public Integer getTotalSeats(){return totalSeats;} }
